WFJ.Data.add("book", {
  ["9c06bb26cb6093c9"] = { "この稼業に身を置いていることを、ここ数年ほど誇らしく思ったことはない。暗殺者、密偵、斥候の需要がこれほど高まったことはなかった。戦時のほうが需要は高いと思うだろうが、意外にも、俺たちが栄えるのは戦時じゃない。今のような時代、つまり平和が崩れ始めた後の時代なんだ。\n\n君がこのあたりで何か学ぼうとしていると聞いた。時間ができたら、修道院の裏手の厩舎のそばまで会いに来てくれ。\n\n-ローグのトレーナー、Jorik Kerridan", "." },
  ["9c3d6e995972970d"] = { "オークと人間がFirst Warで激突する10000年前、Azerothの世界には、果てしなく荒れ狂う海に囲まれた巨大な大陸がただ一つあるのみだった。Kalimdorと呼ばれたその大地には、目覚めつつある世界の荒々しい自然の中で生き残りを競い合う、多種多様な種族や生き物が暮らしていた。その暗き大陸の中心には、白熱のエネルギーをたたえた神秘の湖があった。", "." },
  ["9c84c3994b633a5f"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">HORDEの軍階級</H1><BR/>\n<P align=\"center\">士官</P><BR/>\n<P align=\"center\">High Warlord</P>\n<P align=\"center\">Warlord</P>\n<P align=\"center\">General</P>\n<P align=\"center\">Lieutenant General</P>\n<P align=\"center\">Champion</P>\n<P align=\"center\">Centurion</P>\n<P align=\"center\">Legionnaire</P>\n<P align=\"center\">Blood Guard</P>\n<P align=\"center\">Stone Guard</P><BR/>\n<P align=\"center\">下士官・兵</P><BR/>\n<P align=\"center\">First Sergeant</P>\n<P align=\"center\">Senior Sergeant</P>\n<P align=\"center\">Sergeant</P>\n<P align=\"center\">Grunt</P>\n<P align=\"center\">Scout</P>\n</BODY>\n</HTML>", "." },
  ["9c8bf8d5346384cb"] = { "Ameth'Aranの陥落\n\n魔法の森の古木が根こそぎ倒され、大地が震えた。Cenariusの息子と娘たちが守る木立と林間の空き地、そしてChildren of the Starsの石の塔は、揺れ動く大地へと崩れ落ちた。そこにわれらが女王がいた。絶望の中にあってもなお、戦いという混沌の中にあってもなお、光り輝いていた。魔法の空は、放たれる魔力と、世界を引き裂かんばかりの爆発によって色を変えた。", "." },
  ["9cbcbe3c95910fd6"] = { "冒険者諸君、ごきげんよう！\n\n私、Krinkle Goodsteelは、身の危険を顧みず、とりわけ骨の折れる仕事をいくつか片づけてくれる者を求めている。多くの務めを抱え、自ら引き受けた仕事も山積みなのでね、このリストの品を揃えて無傷で私のもとへ届けてくれる勇敢な者には、たっぷり報酬を払うと約束しよう。\n\nリストは次のページ以降に載っている……", "." },
  ["9cc681308f3ab1dd"] = { "Badlandsは敵だらけだ。Ogresは灼熱の砂地をうろつき、油断した者を待ち伏せる。Dark IronのドワーフはKargathの東の兵舎に住みつき、北のLoch Modanにいる肌の色の薄い同族と戦っている。Troggsと呼ばれる残忍で原始的な獣は、見つけたわずかな日陰にでも棲みつき、それを猛然と守る。\n\nそしてBadlandsの東部、Lethlor Ravineにはドラゴンがいる。何匹いるのか、どれほど大きいのかは分からない。近づきすぎた斥候は二度と戻らないからだ。", "." },
  ["9ceae0f20e65ab20"] = { "女王を失ったDark Ironsは、Wildhammersの怒りを前に逃げ出した。彼らは王の砦を目指して南へと急いだが、Grim Batolの救援に駆けつけていたIronforgeの軍勢と鉢合わせただけであった。2つの軍勢に挟み撃ちにされ、残ったDark Ironの軍は完全に壊滅した。", "." },
})
